PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE devices (     id TEXT PRIMARY KEY,     status TEXT,     last_seen INTEGER,     last_ip TEXT,     updated_at TEXT , lan TEXT DEFAULT 'unknown', wifi TEXT DEFAULT 'unknown', battery TEXT DEFAULT 'unknown');
CREATE TABLE messages (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user TEXT,     content TEXT,     timestamp INTEGER,     session_id TEXT );
CREATE TABLE online_users (     session_id TEXT PRIMARY KEY,     user_name TEXT,     last_seen INTEGER,     ip TEXT );
CREATE TABLE activity_history (     id INTEGER PRIMARY KEY AUTOINCREMENT,     device_id TEXT NOT NULL,     window_title TEXT NOT NULL,     lan TEXT DEFAULT 'unknown',     wifi TEXT DEFAULT 'unknown',     battery TEXT DEFAULT 'unknown',     recorded_at INTEGER NOT NULL , started_at  INTEGER, duration_ms INTEGER);
CREATE TABLE ai_usage (
  day      TEXT,
  provider TEXT,
  count    INTEGER,
  PRIMARY KEY (day, provider)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_history_device_time ON activity_history (device_id, recorded_at DESC);
CREATE INDEX idx_history_time ON activity_history (recorded_at DESC);
CREATE INDEX idx_ah_dev_time ON activity_history(device_id, recorded_at);
CREATE INDEX idx_ah_time     ON activity_history(recorded_at);
CREATE INDEX idx_msg_time    ON messages(timestamp);
CREATE INDEX idx_ou_seen     ON online_users(last_seen);
PRAGMA defer_foreign_keys=TRUE;
